local class = require(script.Parent.Parent.apis.class)
local BaseComponent = require(script.Parent.Parent.apis.BaseComponent)
local module = class(script.Name, BaseComponent)

local TweenService = game:GetService("TweenService")
local PresetTween = TweenInfo.new(0.5)

function module:ctor(element)
    self.super.ctor(self, element)
end

function module:SetProgress(pro, notForce)
	if not notForce then
		if self._changed then
			self._changed:Disconnect()
			self._changed = nil
		end
		
		if self._tween then
			self._tween:Cancel()
			self._tween = nil
		end
	end
    local uigradient = self._element
    pro = math.clamp(pro, 0, 1)
	local ns = nil
	if pro == 0 then
		ns = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 1),
			NumberSequenceKeypoint.new(1, 1)
		})
	elseif pro == 1 then
		ns = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0),
			NumberSequenceKeypoint.new(1, 0)
		})
	else
		pro = math.floor(1000 * pro) / 1000
		local pro2 = pro + 0.0001
		ns = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0),
			NumberSequenceKeypoint.new(pro, 0),
			NumberSequenceKeypoint.new(pro2, 1),
			NumberSequenceKeypoint.new(1, 1)
		})
	end
	uigradient.Transparency = ns
end

function module:TweenProgress(from, to, tweenInfo: TweenInfo)
	if self._changed then
		self._changed:Disconnect()
		self._changed = nil
	end
	
	if self._tween then
		self._tween:Cancel()
		self._tween = nil
	end
	
	tweenInfo = tweenInfo or PresetTween
	self:SetProgress(from, true)
	local numberValue = Instance.new("NumberValue")
	numberValue.Value = from
	self._changed = numberValue.Changed:Connect(function(value: number) 
		self:SetProgress(numberValue.Value, true)
	end)
	self._tween = TweenService:Create(numberValue, tweenInfo, {Value = to})
	self._tween:Play()

	game:GetService("Debris"):AddItem(numberValue, tweenInfo.Time + 1)
end

return module